"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[70690],{85783:e=>{e.exports=JSON.parse('{"functions":[{"name":"CanHumanoidSprint","desc":"Returns `true` when `humanoid` is in a state that permits sprinting under\\nthe given `rules`.\\n\\nChecks applied (all must pass):\\n1. `humanoid.Health > 0` \u2014 character is alive.\\n2. `humanoid.MoveDirection.Magnitude > rules.MinMoveDirection` \u2014 character\\n   is actually moving.\\n3. The local-space move direction\'s Z component is not greater than\\n   `rules.MaxBackwardComponent` \u2014 character is not moving backwards.\\n4. The horizontal speed of `RootPart.AssemblyLinearVelocity` is at least\\n   `rules.MinHorizontalSpeed` \u2014 character has reached the minimum speed\\n   (prevents sprint activation while standing still due to input lag).","params":[{"name":"humanoid","desc":"The humanoid to evaluate.","lua_type":"Humanoid"},{"name":"rules","desc":"Threshold values that define valid sprint conditions.","lua_type":"Rules"}],"returns":[{"desc":"`true` if all sprint conditions are satisfied.","lua_type":"boolean"}],"function_type":"static","source":{"line":42,"path":"src/ReplicatedStorage/SharedModules/SprintValidation.luau"}}],"properties":[],"types":[],"name":"SprintValidation","desc":"Shared sprint validation helpers used by both the client-side\\n`SprintController` (for prediction) and the server-side `StaminaManager`\\n(as the authoritative check).\\n\\nAll functions are pure \u2014 they read from the provided arguments and have no\\nside-effects \u2014 so the same logic runs identically on both environments.","source":{"line":21,"path":"src/ReplicatedStorage/SharedModules/SprintValidation.luau"}}')}}]);